 return `<section class="room-screen sanctuary-screen room-refined ${rest?'rest-room':'altar-room'}"><div class="room-heading"><div><h1>${rest?'余火营地':'命运祭坛'}</h1><p>${rest?'在余火旁，整理下一次出发。':'让这一层的每一次落骰，都更有分量。'}</p></div><span class="room-use-state ${s.roomUsed?'claimed':''}">${s.roomUsed?`${icon('check')} 已领取`:'本房间 · 一次馈赠'}</span></div>${rest?`<div class="sanctuary-emblem" aria-hidden="true">${icon('rest')}</div><dl class="sanctuary-benefits"><div><dt>生命</dt><dd>${num(s.player.hp)} <span>→</span> ${num(st.maxHp)}</dd></div><div><dt>${s.roomUsed?'当前护盾':'休整护盾'}</dt><dd>${num(s.roomUsed?s.ward:ward)} <small>${s.roomUsed?'':'生命上限的 25%'}</small></dd></div></dl>`:`${dice([ui.forging?ui.rollValues?.[0]||6:value||6],{large:true,rolling:ui.forging})}<dl class="sanctuary-benefits"><div><dt>祝福收益</dt><dd>伤害 +5%～30%</dd></div><div><dt>当前本层加成</dt><dd>+${(s.blessing||0)*5}%</dd></div></dl>`}${button(s.roomUsed?'馈赠已领取':rest?'休整 · 恢复生命与护盾':'投骰 · 领取本层祝福',rest?'rest':'bless','primary',s.roomUsed||ui.busy?'disabled':'')}<p class="room-hint">${rest?'护盾优先吸收反击伤害 · 休整会替换现有护盾':'每点骰面增加 5% 伤害 · 本层有效，进入下一层结束'}<br>${s.roomUsed?'可以继续前往下一房间。':'可以领取后前行，也可以直接离开。'}</p></section>`;
