export function center(s, ui) {
  if (ui.view === 'inventory') return inventoryView(s, ui);
  if (ui.view === 'talents') return talentView(s,ui);
  switch (s.phase) {
    case 'fate': case 'route': return fateView(s, ui);
    case 'combat': return combatView(s, ui);
    case 'chest': return chestView(s);
    case 'loot': return lootView(s);
    case 'blackmarket': case 'merchant': return merchantView(s);
    case 'event': return eventView(s,ui);
    case 'forge': return forgeView(s, ui);
    case 'fusion': return fusionView(s,ui);
    case 'altar': case 'rest': return sanctuaryView(s,ui);
    case 'gold': return `<section class="room-screen gold-screen"><span class="room-symbol">${icon('gold')}</span><h1>遗落的黄金</h1><p>不是每一份馈赠，都需要一场战斗。</p><div class="gold-hoard">${icon('gold')}<strong>+${num(Math.round(65 + depthPower(s.floor) * 22) + s.fate.reduce((a, b) => a + b) * 3)}</strong><span>金币</span></div><p class="room-hint">收下它，让下一次锻造更有底气。</p></section>`;
    case 'dead': return `<section class="room-screen death-screen"><span class="room-symbol">${icon('heart')}</span><h1>余火，尚未熄灭。</h1><p>${esc(s.enemy.name)}暂时挡住了去路。</p><div class="recovery-summary"><h2>在当前房间重燃余火</h2><p>恢复全部生命，重新挑战当前敌人。<br>装备、金币、天赋和已完成的房间全部保留。</p></div><p class="room-hint">也可以先打开背包换装，或投入未用的天赋点。</p></section>`;
    case 'cleared': case 'complete': return `<section class="room-screen milestone-screen"><span class="victory-mark">${s.phase === 'complete' ? 'ABYSS CONQUERED' : 'FLOOR CLEARED'}</span><h1>${s.phase === 'complete' ? '你让永夜，听见了回响。' : '再深一层。'}</h1><p>${s.phase === 'complete' ? '前十层已征服。命运的故事，仍由你继续。' : `${floorName(s)}已肃清。前方，还有尚未打开的宝箱。`}</p><div class="floor-number">${String(s.floor).padStart(2, '0')}<span>深度已抵达</span></div>${s.phase === 'complete' ? `<div class="milestone-stats"><span>${s.counters.kills} 次胜利</span><span>${s.counters.chests} 次开箱</span><span>${num(s.counters.highestDamage)} 最高伤害</span></div>` : ''}<p class="room-hint">进入下一层时恢复全部生命。${s.floor >= 10 ? '新的主题、首领与装备将持续出现。没有终层。' : ''}</p></section>`;
    default: return '';
  }
}
export function primaryAction(s, ui) {
  if (ui.view !== 'game') return { label: '返回地牢', type: 'game', hint: '进度已保留' };
  if(s.phase==='event')return s.event?.status==='resolved'?{label:'继续前行',type:'next',hint:'抉择结果已保存'}:{label:'拒绝并离开',type:'event-choice',id:'leave',hint:'不支付代价 · 保留已有资产'};
  if (s.phase==='chest'&&!canAct(s,{type:'open'})) return {label:'整理背包',type:'inventory',hint:'宝箱已保留 · 回收旧装后继续开箱'};
  const map = { fusion:['离开熔室','next','继续探索'],altar:['继续前行','next','本层祝福'],rest:['离开营地','next','继续探索'],blackmarket:['告别黑市','next','继续探索'], fate: ['决定命运', 'fate', '揭晓本层路线'], route: ['踏入地牢', 'enter', '按顺序探索六个房间'], combat: ['掷骰', 'roll', 'SPACE'], chest: ['打开宝箱', 'open', '金币与装备已在等待'], loot: ['继续前行', 'next', '战利品已保存'], gold: ['收下金币', 'gold', '收下后前往下一房间'], merchant: ['告别行商', 'next', '继续探索'], forge: ['离开锻炉', 'next', '继续探索'], dead: ['重燃余火', 'retry', '保留全部成长'], cleared: ['继续深入', 'descend', '下一层 · 恢复生命'], complete: ['继续挑战', 'descend', '进入进阶深渊'] };
  const [label, type, hint] = map[s.phase]; return { label, type, hint };
}
export function footer(s, ui) {
 const st=stats(s), action=primaryAction(s,ui);
 return `<footer class="game-footer"><div class="status-strip frame"><div class="player-level"><b><small>Lv.</small>${s.player.level}</b><span>旅途之人</span><div class="xp-track"><span style="width:${s.player.xp/xpNeeded(s.player.level)*100}%"></span></div><small>${s.player.xp} / ${xpNeeded(s.player.level)} EXP</small></div><div class="player-health"><div>${icon('heart')}<span>生命</span><b>${num(s.player.hp)} / ${num(st.maxHp)}</b></div><div class="player-health-track"><span style="width:${s.player.hp/st.maxHp*100}%"></span></div><p>${icon('shield')} 护盾 ${num(s.ward||0)} · 防御 ${st.defense}</p></div><div class="player-gold">${icon('gold')}<span>金币<strong>${num(s.player.gold)}</strong></span><small>攻击 ${st.attack}　·　暴击 ${Math.round(Math.min(.9,st.crit+st.critBonus)*100)}%</small></div></div><div class="control-strip"><nav class="main-nav" aria-label="主要导航">${button(`${icon('inventory')}<span>背包</span>`,'inventory',ui.view==='inventory'?'selected':'')}${button(`${icon('talent')}<span>天赋${s.player.talentPoints?`<i>${s.player.talentPoints}</i>`:''}</span>`,'talents',ui.view==='talents'?'selected':'')}</nav><div class="primary-control">${button(`${icon(action.type==='roll'||action.type==='fate'?'dice':action.type==='open'?'chest':'arrow')}<span>${ui.busy?'命运落定中…':action.label}</span>`,action.type,'primary',`${ui.busy?'disabled':''} id="primary-action" ${action.id?`data-id="${action.id}"`:''}`)}<small>${ui.busy?'本次结果已保存':action.hint}</small></div><div class="manual-control">${button(ui.busy?'跳过演出':`${icon('dice')}<span>手动掷骰</span>`,ui.busy?'skip':'game',ui.view==='game'?'selected':'',`aria-current="${ui.view==='game'?'page':'false'}"`)}<small>${diceCount(s)} / 6 战斗骰 · 随时保存</small></div></div></footer>`;
}
export function gameView(s, ui) {
 return `<div class="game-shell" data-scene="${ui.view==='game'?s.phase:ui.view}">${header(s)}<main class="game-layout">${ui.view === 'talents' ? buildRail(s) : routeRail(s)}<div class="center-panel frame ${ui.busy?'busy':''}" id="current-room"><canvas class="scene-fx" aria-hidden="true"></canvas>${center(s,ui)}</div>${ui.view === 'talents' ? buildDetails(s,ui) : ui.view === 'game' && s.phase === 'loot' ? rewardRail(s) : equipmentRail(s)}${footer(s,ui)}</main><div class="bottomline"><span>VER 04.0　 INFINITE ABYSS</span><span>${ui.saveError?esc(ui.saveError):'进度已自动保存'}</span><span>骰下的不是数字，而是另一个世界。</span></div></div>`;
}
export function settingsView(settings, hasSave, hasLegacy=false, rawOnly=false) {
  return `<div class="dialog-heading"><h2 id="dialog-title">旅途设置</h2>${button(icon('close'), 'close-dialog', 'icon-button', 'aria-label="关闭设置"')}</div><p class="settings-note">设置即时生效 · 保存在当前浏览器</p><div class="setting-row"><div><b>掷骰声音</b><p>简洁的骰声与奖励音。</p></div><button role="switch" aria-label="掷骰声音" aria-checked="${settings.sound}" data-action="sound" class="switch"><span></span></button></div><div class="setting-row"><div><b>特效强度</b><p>低特效减少翻滚与粒子，保留点数和结算。</p></div><select id="effects" aria-label="特效强度"><option value="full" ${settings.effects === 'full' ? 'selected' : ''}>标准</option><option value="low" ${settings.effects === 'low' ? 'selected' : ''}>低特效</option></select></div><div class="setting-row"><div><b>界面比例</b><p>按当前窗口同步缩放文字与布局。</p></div><select id="ui-scale" aria-label="界面比例">${[0.9, 1, 1.1].map(v => `<option value="${v}" ${settings.scale === v ? 'selected' : ''}>${Math.round(v * 100)}%</option>`).join('')}</select></div><div class="save-management"><h3>存档管理</h3>${rawOnly?'<p class="danger">当前存档无法安全读取。导出会保留原始字节，供备份或人工转换；不会改写浏览器记录。</p>':''}<p>进度自动保存在当前浏览器。导出 JSON 可备份或迁移；导入前会再次确认。</p><div>${button(rawOnly?'导出不可读取的原始存档':'导出存档', 'export', '', hasSave ? '' : 'disabled')}${button('导入存档', 'import', '')}${button('返回标题', 'home', '')}</div>${hasLegacy?`<div class="legacy-backup"><p>保留升级前的原始格式，可用于回退到旧版。</p>${button('导出升级前原始存档','export-legacy','')}</div>`:''}<input type="file" id="save-file" accept="application/json,.json" hidden></div><div class="danger-zone"><span>重新开始会替换当前进度</span>${button('重新开始', 'new', 'danger quiet')}</div>`;
}
